import json
from pathlib import Path
import pytest

@pytest.fixture(autouse=True)
def task9_observe_deferred_callback(request, monkeypatch):
    if request.node.name != 'test_teardown_clear_does_not_clobber_a_newer_same_session_round_arming_mid_teardown':
        yield
        return
    from Tests.UI import test_skill_install_concurrent_confirms as module
    original = module._DeferredClearApp.call_from_thread
    observations = []
    apps = []
    def observe(app, fn, *args, **kwargs):
        if app not in apps:
            apps.append(app)
        observations.append({'callback_qualname': getattr(fn, '__qualname__', ''), 'zero_args': not args and not kwargs})
        return original(app, fn, *args, **kwargs)
    monkeypatch.setattr(module._DeferredClearApp, 'call_from_thread', observe)
    try:
        yield
    finally:
        for app in apps:
            app.release_clear.set()
        Path('/Users/macbook-dev/.codex/worktrees/console-chat-starts/tldw_chatbook/.superpowers/sdd/2026-10-03-console-pr2995-review-and-merge/task-9-final-qualification-safe-evidence/deferred-callback-observations.json').write_text(json.dumps({'observations':observations,'original_callback_forwarded_unchanged':True,'cleanup_released_test_events_after_assertion_failure':True},indent=2)+'\n')
